using Meziantou.Framework.Csv.Serialization.Metadata;

namespace Meziantou.Framework.Csv.Serialization;

/// <summary>The base class of the serializer contexts generated by the source generator, which provide the metadata of types without reflection.</summary>
/// <remarks>
/// Declare a <see langword="partial"/> class that derives from this class, with a <see cref="CsvSerializableAttribute"/> for each type to serialize.
/// The generator adds a <c>Default</c> instance and a property per type that returns its <see cref="CsvTypeInfo{T}"/>, to pass to the methods of
/// <see cref="CsvSerializer"/>. This works with trimming and Native AOT.
/// </remarks>
/// <example>
/// <code xmlns:ref="urn:meziantou:file-referencer" ref:source="../../../tests/Meziantou.Framework.Csv.Tests/CsvSerializerSourceGenerationTests.cs" ref:region="CsvSerializerContext_Declare" ref:dedent="true">
/// [CsvSerializable(typeof(Product))]
/// [CsvSerializable(typeof(Person))]
/// [CsvSourceGenerationOptions(Separator = ';')]
/// public partial class AppCsvContext : CsvSerializerContext
/// {
/// }
/// </code>
/// </example>
public abstract class CsvSerializerContext : ICsvTypeInfoResolver
{
    /// <summary>Initializes a new instance of the <see cref="CsvSerializerContext"/> class.</summary>
    /// <param name="options">The options of the context, or <see langword="null"/> for the default options. The context uses a copy whose <see cref="CsvSerializerOptions.TypeInfoResolver"/> is the context.</param>
    protected CsvSerializerContext(CsvSerializerOptions? options)
    {
        if (options is not null && ReferenceEquals(options.TypeInfoResolver, this))
        {
            Options = options;
        }
        else
        {
            Options = options is null ? new CsvSerializerOptions { TypeInfoResolver = this } : new CsvSerializerOptions(options) { TypeInfoResolver = this };
        }
    }

    /// <summary>Gets the options of the context. Their <see cref="CsvSerializerOptions.TypeInfoResolver"/> is the context.</summary>
    public CsvSerializerOptions Options { get; }

    /// <inheritdoc/>
    public abstract CsvTypeInfo? GetTypeInfo(Type type, CsvSerializerOptions options);

    /// <summary>Gets the metadata of a type for <see cref="Options"/>, creating it on first use.</summary>
    /// <typeparam name="T">The type.</typeparam>
    /// <returns>The metadata of the type.</returns>
    protected CsvTypeInfo<T> GetOrCreateTypeInfo<T>() => (CsvTypeInfo<T>)Options.GetTypeInfoCore(typeof(T), allowReflection: false);
}
